	title 'Tool Locator--MessageCenter'*****************************************************************			   **	   MessageCenter		   **			   **********************************************************************************************************************************			   **	Copyright (C) 1985-1988,1991	   **	All Rights Reserved		   **	Apple Computer, Inc.	   **			   ******************************************************************* REVISION HISTORY** 2-Dec-91	Dave Lyons for 6.0d60** Hack MessageCenter so that deleting message 1 (list of Pascal* strings to Open/Print, from Finder) automatically deletes* message $11 (new mesage, list of GS/OS strings to Open/Print* from Finder). -- This is needed so that a new app doesn't* accidentally act on message $11 after transferring out of* an old application that didn't know about the new message.*****************************************************************	blanks off	string asis	print push	print off	include 'all.macros'	include '::sys.equs.asm'	INCLUDE 'e16.memory'	include 'tl.equates.asm'	print pop	title ' Imported Addresses';-----------------------------------------------;;   Imported addresses;;-----------------------------------------------	IMPORT EndCall4	IMPORT EndCall8	IMPORT ErrOut4	IMPORT ErrOut8	IMPORT oBusyErr4	IMPORT oEndCall0	eject*****************************************************************MessageCenter	PROC EXPORT** Description**;   IN:    PUSH:WORD - Action:;	                  1	= Add message.;	                  2	= Get message.;	                  3	= Delete message.;          PUSH:WORD - Type.;          PUSH:LONG - Handle.;;  OUT:    None.** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************;;; --- Direct page and stack offsets ----------------------------------;pointer	equ 0hand1	equ pointer+4hand2	equ hand1+4;directPage	equ hand2+4longRet1	equ directPage+2longRet2	equ longRet1+3;theHandle	equ longRet2+3theType	equ theHandle+4theAction	equ theType+2endStack	equ theAction+2;;; --- Message record offsets --------------------------------------------;messNext	equ 0	Handle of next message.messType	equ messNext+4	Message type.messData	equ MessType+2	Message defined data.;messageID	equ $9001	Memory manager ID number.*** added 2-Dec-91 DAL -- when deleting message 1, also delete $11sTheHandle	equ 7	;offsets into stacksTheType	equ sTheHandle+4sTheAction	equ sTheType+2	lda sTheAction,s	cmp #3	;delete	bne @notKludge	lda sTheType,s	dec a	bne @notKludge	pea 3	;action=delete	pea $0011	;message = new Types msg	phx	phx	;handle = ignored	_MessageCenter@notKludge*** end 2-Dec-91;; --- Initialize direct page ------------------------------------------;	phd	Save original direct page.;	tsc	Make room on stack for local direct page.	sec	sbc #directPage	tcs;	inc a	(Direct offset is one more than stack.)	tcd	Switch to direct page in stack.;;; --- Dispatch message task ------------------------------------------;	lda <theAction	dec a	asl a	tax	jsr (messTasks,x)	tax	Put error code in x.;;; --- Clean up stack and exit ----------------------------------------;	lda <longRet1	Move return addresses down over	sta <endStack-6	the parameters passed.	lda <longRet1+2	sta <endStack-4	lda <longRet1+4	sta <endStack-2;	lda <directPage	Restore original direct page.	tcd;	tsc	Free local stack space.	clc	adc #endStack-6	tcs;	txa	Return error code in A.	cmp #1	Set return error flag.	rtl;;;messTasks	DC.W addMessage	DC.W getMessage	DC.W delMessage;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = =;          Add a message to the message	queue.; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = =;;  OUT:    a = error code.;addMessage		; ;	jsr delMessage	First, try to delete exsisting message.;	                  Error doesn't matter.;; --- Allocate a handle and clone the given message ------------------------;	lda <theHandle	Set handle of message tobe cloned.	sta <hand1	lda <theHandle+2	sta <hand1+2;	pha	Space for result.	pha	pea 0	Pass size of needed	handle.	pea 2	(Will be resized anyway.)	pea MessageID	Pass ID number to use.	pea attrNoSpec	Anywhere but special.  (3 Apr 89)	pha	Address, anywhere.	pha	_NewHandle	plx	stx <theHandle	plx	stx <theHandle+2	bcs exit100;	jsr cloneMessage	theHandle = hand1.	bcs exit100;;; --- Link the new message into the message queue --------------------;	jsr getFirst	hand1 = handle of first message.;	pei <hand1+2	Save handle of first message.	pei <hand1;	lda <theHandle	New handle must be a real handle.	ldx <theHandle+2	jsr deref;	pla	Current first message will be after	sta [<pointer]	new message.	pla	sta [<pointer],y;	iny	Set the type field.	iny	lda <theType	sta [<pointer],y;-----------------------------------------------------------;; Kludge to fix Bug In Finder 1.0, 1.1 and 1.2;	cmp #2	; is the message the desktop pattern message?	bne NoKludge	pha	; what is the handle size	pha	pei <hand1+2	pei <hand1	_GetHandleSize	pla	plx	bne NoKludge	; if its > $10000, it cannot right but need not be adjusted	cmp #$28	; if it is >= $28 then it is OK	bcs NoKludge	PushLong #$28	; Make it $28	pei <hand1+2	pei <hand1	_SetHandleSize	lda <hand1	; deref the new handle	ldx <hand1+2	jsr deref	ldy #$08	; copy the lower half of the pattern into	ldx #$18	; the upper half of the pattern@Loop	lda [Pointer],y	phy	txy	sta [Pointer],y	tyx	ply	iny	iny	inx	inx	cpy #$18	bcc @LoopNoKludge;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = =;          Set new first handle in message gueue.; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = =;;   IN:    hand1 = handle of first message.;setNewFirst		; ;	pea 0	System.	pea 2	Memory manager.	pei <hand1+2	New first message.	pei <hand1	_SetWAPexit100	rts	Return error flag from SetWAP.;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = =;          Get a message from the message queue.; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = =;;  OUT:    a = error code.;getMessage		; ;	jsr findMessage	Find the message.	bcs exit200	Was the message found?;;;   IN:    hand1 = handle of message to	clone.;          theHandle = handle of cloned	message.;;  OUT:    Carry set if error and A equals error code.;cloneMessage		; ;	pha	Space for result.	pha	pei <hand1+2	Pass handle of found message.	pei <hand1	_GetHandleSize	Get the size of the	message.	ply	plx	bcs exit200;	sty <hand2	Keep size in 'hand2'.	stx <hand2+2;	phx	Pass size of message.	phy	pei <theHandle+2	Pass the handle given by caller.	pei <theHandle	_SetHandleSize	Given handle = size	of message.	bcs exit200;	pei <hand1+2	Pass handle of found message, source.	pei <hand1	pei <theHandle+2	Pass the handle given by caller.	pei <theHandle	pei <hand2+2	Pass number of bytes to copy.	pei <hand2	_HandtoHandexit200	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = =;          Delete a	message from the message queue.; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = =;;   IN:    theType = message type to delete.;;  OUT:    Carry clear if deleted, set if not found.;          a = error code.;delMessage		; ;	jsr findMessage	bcs exit300	Was the message found?;;; hand1 = message to delete.; hand2 = previous message.; pointer = (hand1).;	pei <hand1+2	Pass dead message handle	pei <hand1	to _DisposeHandle.;;	lda [<pointer]	Get handle of message after dead message.	sta <hand1	ldy #2	lda [<pointer],y	sta <hand1+2;	lda <hand2	Was there a previous message?	ora <hand2+2	bne relink;	jsr setNewFirst	bra exit301;;relink	lda [<hand2]	Dereference preivous message handle.	sta <pointer	lda [<hand2],y	sta <pointer+2;	lda <hand1	Message after dead message, is now	sta [<pointer]	the message after the previous message.	lda <hand1+2	sta [<pointer],y;;exit301	_DisposeHandle	Free dead message (handle on stack).;	                  Return error from DisposeHandle.exit300	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = =;          Get first handle in message gueue.; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = =;;   IN:    None.;;  OUT:    hand1 = handle of first message.;          hand2 = zero.;          pointer = (hand1);          BEQ if no first message.;getFirst		; ;	stz <hand2	stz <hand2+2;	pha	Space for result.	pha	pea 0	System.	pea 2	Memory manager's.	_GetWAP	pla	Handle of first message.	plx;;; = = = = = = = = =	= = = = = = = = = =;          Dereference handle.; = = = = = = = = =	= = = = = = = = = =;;   IN:    a = low word of handle.;          x = high	word of handle.;;  OUT:    hand1 = given handle.;          pointer = (hand1).;          y = 2.;          BEQ if hand1 was zero.;deref	sta <hand1	stx <hand1+2;	lda [<hand1]	Dereference the message handle.	sta <pointer	ldy #2	lda [<hand1],y	sta <pointer+2;	lda <hand1	ora <hand1+2	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = =;          Find a message in the message gueue.; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = =;;   IN:    theType = message type to delete.;;  OUT:    Carry clear if found:;            hand1 = handle of message found.;            hand2 = handle of message before found message	(zero if first).;            pointer = (hand1);          Carry set if not found:;            a = error code.;findMessage		; ;	jsr getFirst	Get handle of first	message.	beq exit401	Are there any messages?;lop400	lda [<pointer],y	(Get high word handle of next message)	tax	(while Y is set correctly.);	iny	Match type.	iny	lda [<pointer],y	This message's type.	cmp <theType	Match?	clc	Found flag, just in	case.	beq exit400;	lda <hand1	Remember previous handle.	sta <hand2	lda <hand1+2	sta <hand2+2;	lda [<pointer]	Get handle of next message.;	                  X	already equals high	word.;enter400	jsr deref	bne lop400	Any more messages?;exit401	lda #MessNotFound	sec	Message not found flag.exit400	rts	ENDP	END